   if($x.bf16_mismatches -ne 0 -or -not $x.norm_bits_equal -or ($x.mode -eq 2 -and $x.scaled_selected_cells_cpu -le 0)){throw 'Missing exact normal fallback coverage'}
  }elseif($x.kind -eq 'routed_compaction_comparison'){
